def is_balanced(s):
    """Return True iff the brackets in s are balanced and correctly nested.
    Brackets are (), [], {}; other characters are ignored. Order matters:
    '([)]' is NOT balanced."""
    stack = []
    matching = {')': '(', ']': '[', '}': '{'}
    opening = set('([{')
    closing = set(')]}')
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in closing:
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
    return len(stack) == 0
